<script>
 import { Feather, BookOpen, GitBranch, Play, Plus, ChevronRight, ArrowLeft, Settings2, Download, X, Sparkles, Check, Search, Map, Trash2, Moon, ScrollText, Castle, CircleHelp } from 'lucide-svelte';
 import { onMount } from 'svelte';
 let scenes = $state([
 {id:1,title:'The letter that found you',tag:'The beginning',text:'The letter arrived at precisely midnight.\n\nNot through the letterbox, nor beneath the door, but floating on a current of cold air that smelled faintly of rain and ancient stone. It settled on your windowsill, its emerald wax seal glimmering in the moonlight.\n\nYour name was written in a hand you had never seen before. And yet, somehow, you recognised it.\n\nOutside, an owl watched. Waiting.',choices:[{label:'Break the emerald seal',target:2},{label:'Follow the mysterious owl',target:3}]},
 {id:2,title:'An invitation to the impossible',tag:'Discovery',text:'The seal broke with a soft flash of green light.\n\n“Dear apprentice,” the letter began, “there are doors in this world that open only for those who have forgotten to stop believing.”\n\nBeneath the words, a map slowly drew itself in silver ink. At its centre stood a castle you had dreamed of a hundred times.',choices:[{label:'Find the hidden station',target:4},{label:'Read the silver inscription',target:5}]},
 {id:3,title:'On the wings of night',tag:'A different path',text:'You opened the window. The owl spread its wings, scattering tiny sparks across the night.\n\nAcross the rooftops, a winding stairway of starlight appeared. You took a breath, then stepped into the impossible.',choices:[{label:'Climb the starlit stairway',target:4}]},
 {id:4,title:'Beyond the iron gates',tag:'Arrival',text:'The castle rose from the mist like a memory made of stone. A thousand windows glowed with candlelight.\n\nAt the gates, a woman in midnight-blue robes smiled. “We wondered when you would arrive.”\n\nYou stepped across the threshold. Your story had only just begun.',choices:[]},
 {id:5,title:'The forgotten spell',tag:'A secret ending',text:'The silver letters rearranged themselves beneath your fingertips.\n\nYou whispered the words, and the room blossomed into a forest of stars. Somewhere in the distance, a bell rang thirteen times.\n\nYou had found the magic that had been waiting for you all along.',choices:[]}
 ]);
 let selected=$state(1), tab=$state('write'), playing=$state(false), playId=$state(1), history=$state([]), toast=$state(''), query=$state(''), saved=$state(false), title=$state('The Midnight Invitation'), modal=$state(false);
 let scene=$derived(scenes.find(s=>s.id===selected) || scenes[0]);
 let playScene=$derived(scenes.find(s=>s.id===playId)||scenes[0]);
 let words=$derived(scenes.reduce((n,s)=>n+s.text.trim().split(/\s+/).filter(Boolean).length,0));
 onMount(()=>{try {let data=JSON.parse(localStorage.getItem('enchanted-quill'));if(data?.scenes?.length){scenes=data.scenes;title=data.title||title;selected=scenes[0].id;}}catch{} saved=true;});
 $effect(()=>{if(saved){localStorage.setItem('enchanted-quill',JSON.stringify({scenes,title}));}});
 function notify(t){toast=t;setTimeout(()=>toast='',2800);}
 function addScene(){let id=Math.max(...scenes.map(s=>s.id))+1;scenes.push({id,title:'An unwritten adventure',tag:'New scene',text:'',choices:[]});selected=id;tab='write';notify('A new page in your story.');}
 function addChoice(){scene.choices.push({label:'A new possibility',target:scenes.find(s=>s.id!==scene.id)?.id||scene.id});}
 function exportStory(){let blob=new Blob([JSON.stringify({title,scenes},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='enchanted-story.json';a.click();URL.revokeObjectURL(a.href);notify('Your story has been exported.');}
 function removeScene(){if(scenes.length===1)return;let id=scene.id;scenes=scenes.filter(s=>s.id!==id);scenes.forEach(s=>s.choices=s.choices.filter(c=>c.target!==id));selected=scenes[0].id;notify('Scene removed.');}
</script>

<svelte:head><link rel="preconnect" href="https://fonts.googleapis.com"/><link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700;800&family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"/></svelte:head>

<div class="app">
 <aside class="sidebar">
  <a class="brand" href="/" onclick={(e)=>{e.preventDefault();tab='write';}}><div class="brand-mark"><Feather size={29}/></div><span>THE ENCHANTED<br/><strong>QUILL</strong></span></a>
  <div class="workspace-label">YOUR WRITING DESK <Sparkles size={12}/></div>
  <button class:active={tab==='write'} class="nav" onclick={()=>tab='write'}><BookOpen size={18}/> Story editor <span class="nav-count">01</span></button>
  <button class:active={tab==='map'} class="nav" onclick={()=>tab='map'}><GitBranch size={18}/> Story map</button>
  <button class="nav" onclick={()=>{playing=true;playId=scenes[0].id;history=[];}}><Play size={17}/> Play your story</button>
  <div class="side-divider"></div>
  <div class="scenes-heading"><span>CHAPTER I</span><button class="icon" title="Add scene" onclick={addScene}><Plus size={17}/></button></div>
  <label class="search"><Search size={14}/><input placeholder="Find a scene..." bind:value={query}/><span>⌕</span></label>
  <div class="scene-list">{#each scenes.filter(s=>s.title.toLowerCase().includes(query.toLowerCase())) as s,i}
   <button class="scene-link" class:selected={selected===s.id} onclick={()=>{selected=s.id;tab='write';}}><span class="scene-number">{String(s.id).padStart(2,'0')}</span><span>{s.title}</span>{#if selected===s.id}<span class="gold-dot"></span>{/if}</button>
  {/each}</div>
  <button class="add-scene" onclick={addScene}><Plus size={16}/> Add a new scene</button>
  <div class="sidebar-bottom"><div class="quote-mark">“</div><p>Words are our most<br/>inexhaustible source of magic.</p><span>A LITTLE REMINDER</span><div class="side-divider"></div><button class="profile" onclick={()=>modal=true}><div class="avatar">T</div><div><strong>The storyteller</strong><small>Every story starts with you</small></div><Settings2 size={17}/></button></div>
 </aside>
 <main>
  <header><div class="breadcrumb">My stories <ChevronRight size={13}/><span>{title}</span></div><div class="header-actions"><span class="saved"><Check size={13}/> All changes saved</span><button class="export" onclick={exportStory}><Download size={15}/> Export</button><button class="play-button" onclick={()=>{playing=true;playId=scenes[0].id;history=[];}}><Play size={14} fill="currentColor"/> Play story</button></div></header>
  <section class="hero"><div class="hero-shade"></div><div class="stars">✦ <span>✧</span> ✧</div><div class="hero-content"><div class="eyebrow"><span></span> A WORLD WAITING TO BE WRITTEN</div><h1>Your words.<br/>Their <em>destiny.</em></h1><p>Weave a little wonder. Create a story where every choice<br class="desktop"/> opens a door to something extraordinary.</p></div><div class="hero-bottom"><span><Feather size={14}/> THE MAGIC IS IN YOUR HANDS</span><div>CHAPTER I <span>✦</span> THE BEGINNING</div></div></section>
  <section class="story-heading"><div><div class="eyebrow dark">YOUR INTERACTIVE STORY</div><input class="story-title" aria-label="Story title" bind:value={title}/><div class="story-meta"><span><ScrollText size={13}/>{scenes.length} scenes</span><span><GitBranch size={13}/>{scenes.reduce((n,s)=>n+s.choices.length,0)} choices</span><span>{words} words</span><span class="draft">Draft</span></div></div><div class="view-toggle"><button class:chosen={tab==='write'} onclick={()=>tab='write'}><Feather size={14}/> Write</button><button class:chosen={tab==='map'} onclick={()=>tab='map'}><GitBranch size={14}/> Story map</button></div></section>
  {#if tab==='write'}
  <div class="editor-layout"><section class="paper"><div class="paper-top"><span>SCENE {String(scene.id).padStart(2,'0')}</span><div><span class="scene-tag">{scene.tag}</span><button title="Delete scene" class="icon delete" disabled={scenes.length===1} onclick={removeScene}><Trash2 size={14}/></button></div></div><input class="scene-title" aria-label="Scene title" bind:value={scene.title}/><div class="ornament">────── <span>✧</span> ──────</div><textarea class="story-text" aria-label="Scene content" placeholder="Every great adventure begins with a word…" bind:value={scene.text}></textarea><div class="paper-footer"><span><Feather size={12}/> Let the story find its way.</span><span>{scene.text.trim().split(/\s+/).filter(Boolean).length} words</span></div></section>
   <aside class="choices-panel"><div class="choices-title"><GitBranch size={18}/><h2>Where next?</h2></div><p>Every choice is a new beginning.<br/>Give your reader a path to follow.</p>{#each scene.choices as choice,i}<div class="choice-card"><div class="choice-label"><span>CHOICE {i+1}</span><button title="Remove choice" class="icon" onclick={()=>scene.choices.splice(i,1)}><X size={12}/></button></div><input aria-label={`Choice ${i+1} text`} bind:value={choice.label}/><div class="leads">↳ <select aria-label={`Choice ${i+1} destination`} bind:value={choice.target}>{#each scenes as target}<option value={target.id}>{String(target.id).padStart(2,'0')} · {target.title}</option>{/each}</select></div></div>{/each}<button class="add-choice" onclick={addChoice}><Plus size={15}/> Add a choice</button><div class="tip"><Sparkles size={17}/><div><strong>A spark of inspiration</strong><p>The most memorable choices aren't between right and wrong, but between two things worth choosing.</p></div></div><button class="preview-scene" onclick={()=>{playing=true;playId=selected;history=[];}}><Play size={13}/> Preview this scene <ChevronRight size={13}/></button></aside>
  </div>
  {:else}
  <section class="map-panel"><div class="map-intro"><h2>A constellation of possibilities</h2><p>Select a scene to continue writing its story.</p></div><div class="map-nodes">{#each scenes as s}<div class="map-node"><button onclick={()=>{selected=s.id;tab='write';}}><span>SCENE {String(s.id).padStart(2,'0')} {s.id===scenes[0].id?' · START':''}</span><h3>{s.title}</h3><p>{s.text.slice(0,95)}…</p></button>{#each s.choices as c}<div class="connection"><GitBranch size={13}/><span>{c.label}</span><button onclick={()=>{selected=c.target;tab='write';}}>Scene {c.target} →</button></div>{/each}{#if !s.choices.length}<div class="end-label">✦ An ending</div>{/if}</div>{/each}<button class="new-node" onclick={addScene}><Plus size={25}/>Write another possibility</button></div></section>
  {/if}
  <footer><span>THE ENCHANTED QUILL</span><span>Made for the stories only you can tell. <span class="footer-star">✦</span></span><button onclick={()=>modal=true}><CircleHelp size={14}/> A little guidance</button></footer>
 </main>
</div>
{#if toast}<div class="toast"><Check size={16}/>{toast}</div>{/if}
{#if playing}<div class="modal-backdrop"><section class="reader" tabindex="-1" role="dialog" aria-modal="true" aria-label="Story preview"><button class="close-reader icon" title="Close preview" onclick={()=>playing=false}><X/></button><div class="reader-top"><Moon size={22}/><span>{title}</span></div><span class="eyebrow dark">SCENE {String(playScene.id).padStart(2,'0')}</span><h2>{playScene.title}</h2><div class="ornament">────── ✧ ──────</div><div class="reader-text">{playScene.text||'This page is still waiting for its story.'}</div><div class="reader-choices">{#each playScene.choices as c}<button onclick={()=>{history.push(playId);playId=c.target;}}>{c.label}<ChevronRight size={18}/></button>{/each}{#if !playScene.choices.length}<p class="the-end">✦ The end … or another beginning. ✦</p><button onclick={()=>{playId=scenes[0].id;history=[];}}>Begin again <BookOpen size={18}/></button>{/if}</div>{#if history.length}<button class="back" onclick={()=>playId=history.pop()}><ArrowLeft size={14}/> Previous page</button>{/if}</section></div>{/if}
{#if modal}<div class="modal-backdrop"><section class="reader help" tabindex="-1" role="dialog" aria-modal="true" aria-label="Editor guide"><button class="close-reader icon" title="Close guide" onclick={()=>modal=false}><X/></button><Feather size={32}/><h2>A little guidance</h2><p>Name your story, then choose a scene on the left to write. Add choices and choose the scene each one leads to.</p><p>Use <strong>Story map</strong> to explore your branches, and <strong>Play story</strong> to experience them as a reader.</p><p>Your work is saved in this browser. Export a JSON copy to keep a backup.</p><button class="play-button" onclick={()=>modal=false}>Let the magic begin</button></section></div>{/if}

